#[test]
fn validators_characterized() {
    let mut r = Rng(20);
    let mut hits = [0; 4];
    for _ in 0..N {
        let s = text(&mut r);
        if validate_storage_key(&s).is_ok() {
            hits[0] += 1;
            assert!(s.is_ascii() && !s.contains(&0) && !s.contains(&b'\\') && s[0] != b'/');
            assert!(s.split(|&c| c == b'/').all(|seg| seg != b"." && seg != b".."));
        }
        if validate_docker_name(&s).is_ok() {
            hits[1] += 1;
            assert!(s.len() <= 256);
            assert!(s.split(|&c| c == b'/').all(|seg| !seg.is_empty() && seg[0].is_ascii_alphanumeric()
                && seg.iter().all(|&c| c.is_ascii_lowercase() || c.is_ascii_digit() || b"_.-".contains(&c))));
        }
        let digest_shape = |d: &[u8]| (d.starts_with(b"sha256:") && d.len() == 71 && d[7..].iter().all(|&c| is_lower_hex(c)))
            || (d.starts_with(b"sha512:") && d.len() == 135 && d[7..].iter().all(|&c| is_lower_hex(c)));
        let ok = validate_digest(&s).is_ok();
        assert_eq!(ok, digest_shape(&s), "{s:?}");
        hits[2] += ok as usize;
        if validate_docker_reference(&s).is_ok() {
            hits[3] += 1;
            assert!(digest_shape(&s) || (s.len() <= 128 && s[0].is_ascii_alphanumeric()
                && s.iter().all(|&c| c.is_ascii_alphanumeric() || b"._-".contains(&c))));
        }
    }
    assert!(hits.iter().all(|&h| h >= MIN_HITS), "{hits:?}");
}

#[test]
fn validation_agrees() {
    let mut r = Rng(0xA5A5_1234_5678_9ABC);
    let mut ok = [0usize; 4];
    for _ in 0..2_000_000 {
        let s = text(&mut r);
        let b = s.as_bytes();
        let pairs = [
            (k::validate_storage_key(b), up::validate_storage_key(&s).map_err(map)),
            (k::validate_docker_name(b), up::validate_docker_name(&s).map_err(map)),
            (k::validate_digest(b), up::validate_digest(&s).map_err(map)),
            (k::validate_docker_reference(b), up::validate_docker_reference(&s).map_err(map)),
        ];
        for (i, (got, want)) in pairs.into_iter().enumerate() {
            assert_eq!(got, want, "validator {i} on {s:?}");
            ok[i] += got.is_ok() as usize;
        }
        let t = text(&mut r);
        assert_eq!(k::ends_with_ci(b, t.as_bytes()), up::ends_with_ci(&s, &t), "{s:?} {t:?}");
    }
    // Every validator accepts some inputs.
    assert!(ok.iter().all(|&n| n > 100), "{ok:?}");
}
